package com.aoo.bcg.bootstrap;
import com.aoo.bcg.common.settlement.*;import com.aoo.bcg.gamespi.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
final class DurableGameSettlementServiceTest{
 @Test void persistsByStableBusinessIdAndReturnsSameResultOnRetry(){Map<String,SettlementResult>stored=new HashMap<>();SettlementRepository repo=new SettlementRepository(){public SettlementResult save(String id,SettlementResult result){var old=stored.putIfAbsent(id,result);if(old!=null&&!old.equals(result))throw new IllegalArgumentException();return old==null?result:old;}public Optional<SettlementResult>find(String id){return Optional.ofNullable(stored.get(id));}};GameRegistry registry=new GameRegistry();registry.register(new GameProvider(){final GameDescriptor d=new GameDescriptor(7,"test","test",GameCategory.POKER,"poker-test",RegionScope.NATIONAL,"","","v1");public GameDescriptor descriptor(){return d;}public GameRoomFactory roomFactory(){return c->null;}public Optional<SettlementProvider>settlementProvider(){return Optional.of((room,round)->new SettlementPayload(room.roomId(),round,room.playVersion(),Map.of(10L,5L,11L,-5L)));}});var service=new DurableGameSettlementService(registry,new SettlementExecutor(repo));var room=new GameRoomHandle(99,7,"v1",Map.of());assertEquals(service.settle(room,1),service.settle(room,1));assertEquals(1,stored.size());assertTrue(stored.containsKey("round:99:1:v1"));}
}
